const P1 = { pedido: "P1", articulo: "A1", almacen: "LPZ" };

test("RF-006: reservar no mueve el stock físico y baja el disponible", () => {
  const antes = conIngreso();
  const despues = reservar(antes, { ...P1, cantidad: 4 });
  assert.equal(antes.length, 1);
  assert.equal(stock(despues, "A1", "LPZ"), 10);
  assert.equal(reservado(despues, "A1", "LPZ"), 4);
  assert.equal(disponible(despues, "A1", "LPZ"), 6);
  assert.ok(!("stock" in despues[1]));
});

test("RF-006: no se reserva más que el disponible ni sin pedido", () => {
  const movs = reservar(conIngreso(), { ...P1, cantidad: 8 });
  assert.throws(() => reservar(movs, { ...P1, pedido: "P2", cantidad: 3 }), /Disponible insuficiente/);
  assert.throws(() => registrarMovimiento(conIngreso(), { tipo: "reserva", articulo: "A1", almacen: "LPZ", cantidad: 1 }), /pedido/);
});

test("RF-006: lo reservado no se vende dos veces (egreso de otro)", () => {
  const movs = reservar(conIngreso(), { ...P1, cantidad: 8 });
  assert.throws(() => registrarMovimiento(movs, { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 3 }), /reservado/);
  const ok = registrarMovimiento(movs, { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 2 });
  assert.equal(stock(ok, "A1", "LPZ"), 8);
});

test("RF-006: liberar es un movimiento inverso y devuelve disponible", () => {
  const movs = reservar(conIngreso(), { ...P1, cantidad: 8 });
  const libre = liberar(movs, { ...P1, cantidad: 8 });
  assert.equal(libre.length, 3);
  assert.equal(disponible(libre, "A1", "LPZ"), 10);
  assert.throws(() => liberar(libre, { ...P1, cantidad: 1 }), /no tiene reservado/);
  assert.throws(() => liberar(movs, { ...P1, pedido: "P2", cantidad: 1 }), /no tiene reservado/);
});

test("RF-006: despachar consume la reserva del pedido y respeta RF-002", () => {
  const movs = reservar(conIngreso(), { ...P1, cantidad: 8 });
  const sale = despachar(movs, { ...P1, cantidad: 8 });
  assert.equal(stock(sale, "A1", "LPZ"), 2);
  assert.equal(reservado(sale, "A1", "LPZ"), 0);
  assert.throws(() => despachar(movs, { ...P1, cantidad: 9 }));
});
